        require(method.getDefiningClass().equals(
                        contractSpec.fetchWorkerRunMethod.owner)
                        && method.getName().equals(
                                contractSpec.fetchWorkerRunMethod.name)
                        && methodDescriptor(method).equals(
                                contractSpec.fetchWorkerRunMethod.descriptor)
                        && (method.getAccessFlags() & 0x8) == 0,
                code + "_definition");
        MethodView view = new MethodView(method, false);
        verifyNoUnreviewedImplicitThrow(
                view, code + "_unreviewed_implicit_throw");
