    private static int verifyAutomaticPacingRunnable(
            MethodView view, Map<String, ClassDef> classes, int afterIndex, String code)
            throws ContractFailure {
        int delayCall = oneResolvedCall(
                view, classes, contractSpec.millisUntilPaceAllowed,
                code + "_delay_call");
        require(delayCall > afterIndex, code + "_delay_order");
        int[] delayRegisters = invocationRegisters(view.code.get(delayCall).instruction);
        require(delayRegisters.length == 2, code + "_delay_arguments");
        require(delayCall >= 2
                        && fieldReadRegister(
                                view.code.get(delayCall - 2).instruction,
                                "IGET_OBJECT", view.thisRegister,
                                contractSpec.automaticCaller, "activity", ACTIVITY,
                                code + "_delay_entry") == delayRegisters[0]
                        && fieldReadRegister(
                                view.code.get(delayCall - 1).instruction,
                                "IGET_OBJECT", view.thisRegister,
                                contractSpec.automaticCaller, "viewer", STRING,
                                code + "_delay_entry") == delayRegisters[1],
                code + "_delay_entry");
        int paceEntry = delayCall - 2;
        requireDominatedReachability(
                view, afterIndex, paceEntry, delayCall,
                code + "_delay_entry_dominance");
        requireFieldArgument(
                view, delayCall, delayRegisters[0], contractSpec.automaticCaller,
                "activity", ACTIVITY, code + "_delay_arguments");
        requireFieldArgument(
                view, delayCall, delayRegisters[1], contractSpec.automaticCaller,
                "viewer", STRING, code + "_delay_arguments");
        int delayResult = moveResultWideRegister(view, delayCall, code + "_delay_result");

        List<Integer> posts = callIndexes(view, contractSpec.handlerPostDelayed);
        require(posts.size() == 1, code + "_post_count");
        int post = posts.get(0);
        require(post > delayCall, code + "_post_order");
        int[] postRegisters = invocationRegisters(view.code.get(post).instruction);
        require(postRegisters.length == 4 && postRegisters[2] == delayResult
                        && postRegisters[3] == delayResult + 1,
                code + "_delay_identity");
        require(sourcedOrigin(
                        "RESULT", delayCall + ":lo", delayCall + 1).equals(
                                originAt(view, post, delayResult))
                        && sourcedOrigin(
                                "RESULT", delayCall + ":hi", delayCall + 1).equals(
                                        originAt(view, post, delayResult + 1)),
                code + "_delay_register_mutated");
        require(resolvesFromAutoBlockMainHandler(
                        view, post, postRegisters[0], classes,
                        code + "_handler"),
                code + "_handler");
        int runnableRegister = postRegisters[1];
        String runnableOrigin = originAt(view, post, runnableRegister);
        require(runnableOrigin != null && runnableOrigin.startsWith("NEW:L"),
                code + "_runnable_provenance");
        int allocationSeparator = runnableOrigin.lastIndexOf('#');
        require(allocationSeparator > "NEW:".length(),
                code + "_runnable_provenance");
        String runnableType = runnableOrigin.substring(
                "NEW:".length(), allocationSeparator);
        int allocation;
        try {
            allocation = Integer.parseInt(runnableOrigin.substring(allocationSeparator + 1));
        } catch (NumberFormatException ignored) {
            throw new ContractFailure(code + "_runnable_provenance");
        }
        require(allocation >= 0 && allocation < post && isClassDescriptor(runnableType)
                        && isTypeInstruction(
                                view.code.get(allocation).instruction,
                                "NEW_INSTANCE", runnableRegister, runnableType),
                code + "_runnable_provenance");
        requireDominatedReachability(
                view, afterIndex, allocation, post,
                code + "_runnable_allocation_dominance");
        int constructor = -1;
        for (int index = allocation + 1; index < post; index++) {
            Instruction instruction = view.code.get(index).instruction;
            if (!(instruction instanceof ReferenceInstruction)
                    || !instruction.getOpcode().name().equals("INVOKE_DIRECT")) continue;
            Reference reference = ((ReferenceInstruction) instruction).getReference();
            if (!(reference instanceof MethodReference)) continue;
            MethodReference invoked = (MethodReference) reference;
            if (!runnableType.equals(invoked.getDefiningClass())
                    || !"<init>".equals(invoked.getName())
                    || !("(" + contractSpec.automaticCaller + ")V")
                            .equals(methodDescriptor(invoked))) continue;
            require(constructor < 0, code + "_runnable_constructor");
            constructor = index;
        }
        require(constructor >= 0, code + "_runnable_constructor");
        int[] constructorRegisters = invocationRegisters(
                view.code.get(constructor).instruction);
        require(constructorRegisters.length == 2
                        && constructorRegisters[0] == runnableRegister
                        && resolvesToRegister(
                                view, constructor, constructorRegisters[1],
                                view.thisRegister),
                code + "_runnable_constructor");
        requireDominatedReachability(
                view, allocation, constructor, post,
                code + "_runnable_constructor_dominance");
        require(sourcedOrigin("NEW", runnableType, allocation).equals(
                        originAt(view, constructor, runnableRegister))
                        && sourcedOrigin("NEW", runnableType, allocation).equals(
                                originAt(view, post, runnableRegister)),
                code + "_runnable_register_mutated");

        ClassDef runnableClass = classes.get(runnableType);
        require(runnableClass != null, code + "_runnable_class");
        verifyOnlyInterface(runnableClass, RUNNABLE, code + "_runnable_interface");
        require(methodCount(runnableClass) == 2, code + "_runnable_method_count");
        Method ctor = oneMethod(
                runnableClass, "<init>", "(" + contractSpec.automaticCaller + ")V",
                code + "_runnable_constructor_definition");
        MethodView ctorView = new MethodView(ctor, false);
        require(ctorView.implementation.getTryBlocks().isEmpty(),
                code + "_runnable_constructor_try_count");
        require(ctorView.code.size() == 3
                        && isInstanceFieldWrite(
                                ctorView.code.get(0).instruction, "IPUT_OBJECT",
                                ctorView.parameters[0], ctorView.thisRegister,
                                runnableType, "this$0", contractSpec.automaticCaller)
                        && referenceMatches(
                                ctorView.code.get(1).instruction,
                                contractSpec.objectConstructor)
                        && isReturnVoid(ctorView.code.get(2).instruction),
                code + "_runnable_constructor_definition");
        Method runMethod = oneMethod(
                runnableClass, "run", "()V", code + "_runnable_run_definition");
        MethodView run = new MethodView(runMethod, false);
        require(run.implementation.getTryBlocks().isEmpty(),
                code + "_runnable_run_try_count");
        require(run.code.size() == 3, code + "_runnable_run_shape");
        int ownerRegister = fieldReadRegister(
                run.code.get(0).instruction, "IGET_OBJECT", run.thisRegister,
                runnableType, "this$0", contractSpec.automaticCaller,
                code + "_runnable_run_field");
        require(invocationResolvesTo(
                        run.code.get(1).instruction, classes,
                        contractSpec.automaticNext, code + "_runnable_next"),
                code + "_runnable_next");
        int[] nextRegisters = invocationRegisters(run.code.get(1).instruction);
        require(nextRegisters.length == 1 && nextRegisters[0] == ownerRegister
                        && isReturnVoid(run.code.get(2).instruction),
                code + "_runnable_run_shape");
        return post;
    }

    private static void requireSchedulerTokenArgument(
            MethodView view, int callIndex, int token, int tokenHigh,
            String owner, String code) throws ContractFailure {
        String objectOrigin = registerOrigin(view.thisRegister);
        String lowValue = owner + "->schedulerToken:J|" + objectOrigin + ":lo";
        String highValue = owner + "->schedulerToken:J|" + objectOrigin + ":hi";
        String lowOrigin = originAt(view, callIndex, token);
        int source = sourcedOriginIndex(lowOrigin, "FIELD", lowValue);
        require(source >= 0 && tokenHigh == token + 1
                        && sourcedOrigin("FIELD", highValue, source).equals(
                                originAt(view, callIndex, token + 1))
                        && isExactInstanceFieldRead(
                                view.code.get(source).instruction,
                                "IGET_WIDE", view.thisRegister,
                                owner, "schedulerToken", "J"),
                code);
    }

    private static int schedulerTokenRegister(
            MethodView view, int callIndex, String owner, String code)
            throws ContractFailure {
        int[] registers = invocationRegisters(view.code.get(callIndex).instruction);
        require(registers.length >= 3, code);
        int token = registers[0];
        requireSchedulerTokenArgument(
                view, callIndex, token, registers[1], owner, code);
        return token;
    }

    private static void requireWideFieldArgument(
            MethodView view, int callIndex, int lowRegister,
            String owner, String fieldName, String code)
            throws ContractFailure {
        String objectOrigin = registerOrigin(view.thisRegister);
        String lowValue = owner + "->" + fieldName + ":J|"
                + objectOrigin + ":lo";
        String highValue = owner + "->" + fieldName + ":J|"
                + objectOrigin + ":hi";
        int source = sourcedOriginIndex(
                originAt(view, callIndex, lowRegister),
                "FIELD", lowValue);
        require(source >= 0
                        && sourcedOrigin("FIELD", highValue, source).equals(
                                originAt(view, callIndex, lowRegister + 1)),
                code);
        Instruction instruction = view.code.get(source).instruction;
        require(instruction instanceof TwoRegisterInstruction
                        && isExactInstanceFieldRead(
                                instruction, "IGET_WIDE",
                                ((TwoRegisterInstruction) instruction).getRegisterB(),
                                owner, fieldName, "J")
                        && registerOrigin(view.thisRegister).equals(originAt(
                                view, source,
                                ((TwoRegisterInstruction) instruction).getRegisterB())),
                code);
    }

    private static int oneFieldWriteFromThisOrigin(
            MethodView view, String owner, String name, String type,
            String opcode, String code) throws ContractFailure {
        int found = -1;
        for (int index = 0; index < view.code.size(); index++) {
            Instruction instruction = view.code.get(index).instruction;
            if (!(instruction instanceof TwoRegisterInstruction)
                    || !instruction.getOpcode().name().equals(opcode)) continue;
            FieldReference field = fieldReference(instruction);
            int object = ((TwoRegisterInstruction) instruction).getRegisterB();
            if (field == null || !owner.equals(field.getDefiningClass())
                    || !name.equals(field.getName()) || !type.equals(field.getType())
                    || !registerOrigin(view.thisRegister).equals(
                            originAt(view, index, object))) continue;
            require(found < 0, code);
            found = index;
        }
        require(found >= 0, code);
        return found;
    }

    private static int verifySchedulerOwnershipCall(
            MethodView view, Map<String, ClassDef> classes, String owner,
            long expectedValue, String code) throws ContractFailure {
        int call = oneResolvedCall(
                view, classes, contractSpec.markSchedulerMutationInFlight,
                code + "_count");
        int[] registers = invocationRegisters(view.code.get(call).instruction);
        require(registers.length == 3
                        && resolvesToValue(view, call, registers[2], expectedValue),
                code + "_arguments");
        schedulerTokenRegister(view, call, owner, code + "_token");
        return call;
    }

    private static void verifySuccessInvocationClosure(
            MethodView view, Map<String, ClassDef> classes,
            CheckedPostEvidence checked, boolean automatic, String code)
            throws ContractFailure {
        List<CallSpec> allowed = automatic
                ? Arrays.asList(
                        contractSpec.automaticIsCurrent,
                        contractSpec.markDone,
                        contractSpec.automaticHandleCompletionPersistence,
                        contractSpec.markSchedulerMutationInFlight,
                        contractSpec.recordAutomaticBlocked,
                        contractSpec.clearRetryDeadline,
                        contractSpec.stringBuilderConstructor,
                        contractSpec.stringBuilderAppend,
                        contractSpec.stringBuilderAppendInt,
                        contractSpec.stringBuilderToString,
                        contractSpec.setStatus,
                        contractSpec.blockLimitsLoad,
                        contractSpec.blockLimitsMaxPerRun,
                        contractSpec.automaticIsCurrentForeground,
                        contractSpec.automaticFinishForForegroundChange,
                        contractSpec.millisUntilPaceAllowed,
                        contractSpec.handlerPostDelayed,
                        contractSpec.automaticFinish)
                : Arrays.asList(
                        contractSpec.manualIsCurrent,
                        contractSpec.atomicCompareAndSet,
                        contractSpec.markManualBlocked,
                        contractSpec.manualHandleCompletionPersistence,
                        contractSpec.markSchedulerMutationInFlight,
                        contractSpec.clearRetryDeadline,
                        contractSpec.setStatus,
                        contractSpec.recordRuntimeState,
                        contractSpec.dispatchManualSuccess,
                        contractSpec.millisUntilPaceAllowed,
                        contractSpec.releaseSchedulerAndContinue);
        for (int index = 0; index < view.code.size(); index++) {
            Instruction instruction = view.code.get(index).instruction;
            if (!instruction.getOpcode().name().startsWith("INVOKE_")) continue;
            if (automatic && checked != null
                    && index == checked.runnableConstructor) continue;
            boolean accepted = false;
            for (CallSpec candidate : allowed) {
                if (invocationResolvesTo(
                        instruction, classes, candidate,
                        code + "_accessor")) {
                    accepted = true;
                    break;
                }
            }
            if (!accepted && automatic) {
                accepted = invocationIsSyntheticStaticFieldGetter(
                        instruction, classes,
                        contractSpec.isSchedulerOwner.owner,
                        "MAIN", "Landroid/os/Handler;",
                        code + "_main_accessor");
            }
            require(accepted, code);
        }
    }

    private static int verifyAutomaticSuccessLegacy(
            Method method, Map<String, ClassDef> classes, VerificationResult result,
            String code) throws ContractFailure {
        MethodView view = new MethodView(method, false);
        verifyNoUnreviewedImplicitThrow(
                view, code + "_unreviewed_implicit_throw");
        verifyEntryRegisterPreserved(
                view, view.thisRegister, false,
                code + "_receiver_register_mutated");
        verifyAllowedFieldReferences(
                view, new HashSet<>(Arrays.asList(
                        fieldKey(contractSpec.automaticCaller, "activity", ACTIVITY),
                        fieldKey(contractSpec.automaticCaller, "viewer", STRING),
                        fieldKey(contractSpec.automaticCaller, "schedulerToken", "J"),
                        fieldKey(contractSpec.automaticCaller, "waiting", "Z"),
                        fieldKey(contractSpec.automaticCaller, "successesThisRun", "I"),
                        fieldKey(contractSpec.automaticCaller, "attemptsThisRun", "I"),
                        fieldKey(contractSpec.isSchedulerOwner.owner, "MAIN",
                                "Landroid/os/Handler;"))),
                code + "_unreviewed_field");
        verifyExactFieldWrites(
                view, expectedFieldWrites(
                        fieldKey(contractSpec.automaticCaller, "waiting", "Z"),
                        fieldKey(contractSpec.automaticCaller,
                                "successesThisRun", "I")),
                code + "_unreviewed_field_write");
        int save = oneResolvedCall(view, classes, contractSpec.markDone,
                code + "_completion_save");
        int currentTrue = verifyCurrentGuard(
                view, classes, contractSpec.automaticIsCurrent,
                "IF_NEZ", save, code + "_current");
        int[] saveRegisters = invocationRegisters(view.code.get(save).instruction);
        require(saveRegisters.length == 3,
                code + "_completion_save_arguments");
        require(resolvesToRegister(
                        view, save, saveRegisters[2], view.parameters[0]),
                code + "_target_register_mutated");
        requireFieldArgument(view, save, saveRegisters[0], contractSpec.automaticCaller,
                "activity", ACTIVITY, code + "_completion_save_arguments");
        requireFieldArgument(view, save, saveRegisters[1], contractSpec.automaticCaller,
                "viewer", STRING, code + "_completion_save_arguments");
        int savedRegister = moveResultScalarRegister(
                view, save, code + "_completion_save_result");
        int savedBranch = oneBranchAfter(
                view, save, "IF_NEZ", savedRegister,
                code + "_completion_save_branch");
        int quarantine = oneResolvedCall(
                view, classes, contractSpec.automaticHandleCompletionPersistence,
                code + "_completion_quarantine");
        require(quarantine == savedBranch + 1
                        && quarantine + 1 < view.code.size()
                        && isReturnVoid(view.code.get(quarantine + 1).instruction),
                code + "_completion_quarantine_shape");
        int[] quarantineRegisters = invocationRegisters(
                view.code.get(quarantine).instruction);
        require(quarantineRegisters.length == 2
                        && resolvesToRegister(
                                view, quarantine, quarantineRegisters[0],
                                view.thisRegister),
                code + "_completion_quarantine_arguments");
        require(resolvesToRegister(
                        view, quarantine, quarantineRegisters[1],
                        view.parameters[0]),
                code + "_target_register_mutated");
        int successPath = view.indexAt(
                branchTarget(view, savedBranch, "IF_NEZ", savedRegister,
                        code + "_completion_save_branch"),
                code + "_completion_save_branch");
        require(successPath > quarantine + 1, code + "_completion_quarantine_branch");
        int completionHandler = verifyCompletionSaveExceptionFlow(
                view, save, savedBranch, 2,
                code + "_completion_save_exception_flow");
        requireDominatedReachability(
                view, currentTrue, save, savedBranch,
                code + "_completion_save_reachability");
        requireNoTerminalBypass(
                view, currentTrue, save,
                code + "_completion_save_postdominance");
        requireAllExceptionalPathsReachAny(
                view, currentTrue,
                new HashSet<>(Arrays.asList(save, completionHandler)),
                code + "_completion_save_exception_postdominance");

        int release = verifySchedulerOwnershipCall(
                view, classes, contractSpec.automaticCaller, 0,
                code + "_ownership_release");
        require(release >= successPath
                        && !coveredByTry(view, view.code.get(release).offset),
                code + "_ownership_release_order");
        int record = oneResolvedCall(
                view, classes, contractSpec.recordAutomaticBlocked,
                code + "_success_record");
        require(record > release, code + "_success_record_order");
        int[] recordRegisters = invocationRegisters(view.code.get(record).instruction);
        require(recordRegisters.length == 3,
                code + "_success_record_arguments");
        require(resolvesToRegister(
                        view, record, recordRegisters[2], view.parameters[0]),
                code + "_target_register_mutated");
        requireFieldArgument(view, record, recordRegisters[0],
                contractSpec.automaticCaller, "activity", ACTIVITY,
                code + "_success_record_arguments");
        requireFieldArgument(view, record, recordRegisters[1],
                contractSpec.automaticCaller, "viewer", STRING,
                code + "_success_record_arguments");
        int waitingWrite = oneFieldWrite(
                view, contractSpec.automaticCaller, "waiting", "Z", "IPUT_BOOLEAN",
                code + "_waiting_clear");
        int waitingValue = ((TwoRegisterInstruction) view.code.get(waitingWrite).instruction)
                .getRegisterA();
        require(waitingWrite > record
                        && resolvesToZero(view, waitingWrite, waitingValue),
                code + "_waiting_clear");
        verifyAutomaticRecordJoin(
                view, record, waitingWrite, code + "_record_exception_join");
        requireAllExceptionalPathsReachAny(
                view, release + 1,
                new HashSet<>(Arrays.asList(record, waitingWrite)),
                code + "_record_exception_postdominance");
        int clearRetry = oneResolvedCall(
                view, classes, contractSpec.clearRetryDeadline,
                code + "_clear_retry_count");
        int[] clearRetryRegisters = invocationRegisters(
                view.code.get(clearRetry).instruction);
        require(clearRetryRegisters.length == 2,
                code + "_clear_retry_arguments");
        requireFieldArgument(
                view, clearRetry, clearRetryRegisters[0],
                contractSpec.automaticCaller, "activity", ACTIVITY,
                code + "_clear_retry_arguments");
        requireFieldArgument(
                view, clearRetry, clearRetryRegisters[1],
                contractSpec.automaticCaller, "viewer", STRING,
                code + "_clear_retry_arguments");

        int successIncrement = oneFieldWrite(
                view, contractSpec.automaticCaller, "successesThisRun", "I",
                "IPUT", code + "_success_increment_write_count");
        require(successIncrement >= 2,
                code + "_success_increment_shape");
        Instruction incrementRead = view.code.get(successIncrement - 2).instruction;
        Instruction incrementAdd = view.code.get(successIncrement - 1).instruction;
        Instruction incrementWrite = view.code.get(successIncrement).instruction;
        int incrementRegister = ((TwoRegisterInstruction) incrementWrite)
                .getRegisterA();
        require(isExactInstanceFieldRead(
                        incrementRead, "IGET", view.thisRegister,
                        contractSpec.automaticCaller, "successesThisRun", "I")
                        && ((TwoRegisterInstruction) incrementRead).getRegisterA()
                                == incrementRegister
                        && incrementAdd instanceof TwoRegisterInstruction
                        && incrementAdd instanceof WideLiteralInstruction
                        && incrementAdd.getOpcode().name().equals("ADD_INT_LIT8")
                        && ((TwoRegisterInstruction) incrementAdd).getRegisterA()
                                == incrementRegister
                        && ((TwoRegisterInstruction) incrementAdd).getRegisterB()
                                == incrementRegister
                        && ((WideLiteralInstruction) incrementAdd).getWideLiteral() == 1,
                code + "_success_increment_shape");

        int successStatus = oneResolvedCall(
                view, classes, contractSpec.setStatus,
                code + "_success_status_count");
        int[] successStatusRegisters = invocationRegisters(
                view.code.get(successStatus).instruction);
        require(successStatusRegisters.length == 3,
                code + "_success_status_arguments");
        requireFieldArgument(
                view, successStatus, successStatusRegisters[0],
                contractSpec.automaticCaller, "activity", ACTIVITY,
                code + "_success_status_arguments");
        requireFieldArgument(
                view, successStatus, successStatusRegisters[1],
                contractSpec.automaticCaller, "viewer", STRING,
                code + "_success_status_arguments");
        int statusText = resultOriginCall(
                originAt(view, successStatus, successStatusRegisters[2]), false);
        require(statusText >= 0
                        && invocationResolvesTo(
                                view.code.get(statusText).instruction, classes,
                                contractSpec.stringBuilderToString,
                                code + "_success_status_text"),
                code + "_success_status_text");
        require(countLiteral(view, "Synchronized ") == 1
                        && countLiteral(
                                view, " account(s) in this run.") == 1,
                code + "_success_status_literals");
        int statusCountAppend = -1;
        for (int append : callIndexes(
                view, contractSpec.stringBuilderAppendInt)) {
            if (append < successStatus - 15 || append >= successStatus) continue;
            require(statusCountAppend < 0,
                    code + "_success_status_count_argument");
            statusCountAppend = append;
        }
        require(statusCountAppend >= 0,
                code + "_success_status_count_argument");
        int[] statusCountRegisters = invocationRegisters(
                view.code.get(statusCountAppend).instruction);
        require(statusCountRegisters.length == 2,
                code + "_success_status_count_argument");
        requireFieldArgument(
                view, statusCountAppend, statusCountRegisters[1],
                contractSpec.automaticCaller, "successesThisRun", "I",
                code + "_success_status_count_argument");
        require(tryBlockCount(view) == 5,
                code + "_try_count");
        verifySwallowedEffectTry(
                view, clearRetry - 2, clearRetry + 1,
                clearRetry, clearRetry + 3,
                code + "_clear_retry_try");
        verifySwallowedEffectTry(
                view, successStatus - 15, successStatus + 1,
                successStatus, successStatus + 3,
                code + "_success_status_try");
        require(waitingWrite < clearRetry && clearRetry < successIncrement
                        && successIncrement < successStatus,
                code + "_post_save_effect_order");
        requireNoTerminalBypass(
                view, waitingWrite, clearRetry,
                code + "_clear_retry_postdominance");
        requireNoTerminalBypass(
                view, clearRetry, successIncrement,
                code + "_success_increment_postdominance");
        requireNoTerminalBypass(
                view, successIncrement, successStatus,
                code + "_success_status_postdominance");
        int post = verifyAutomaticPacingRunnable(
                view, classes, record, code + "_pacing");
        CheckedPostEvidence checkedPacing = verifyCheckedMainPost(
                view, post, contractSpec.handlerPostDelayed,
                classes, successPath, code + "_pacing_enqueue");
        int pacingRefusalFinish = oneRefusalCall(
                view, classes, checkedPacing, contractSpec.automaticFinish,
                code + "_pacing_enqueue_refusal_finish");
        int[] pacingRefusalRegisters = invocationRegisters(
                view.code.get(pacingRefusalFinish).instruction);
        require(pacingRefusalRegisters.length == 2
                        && resolvesToRegister(
                                view, pacingRefusalFinish,
                                pacingRefusalRegisters[0], view.thisRegister)
                        && resolvesToString(
                                view, pacingRefusalFinish,
                                pacingRefusalRegisters[1],
                                "Scheduler wake was rejected; reopen Threads to resume safely."),
                code + "_pacing_enqueue_refusal_arguments");
        int delay = oneResolvedCall(
                view, classes, contractSpec.millisUntilPaceAllowed,
                code + "_pacing_delay_reachability");
        requireDominatedReachability(
                view, successPath, release, record,
                code + "_release_record_reachability");
        requireDominatedReachability(
                view, successPath, record, delay,
                code + "_record_pacing_reachability");
        requireDominatedReachability(
                view, successPath, delay, post,
                code + "_pacing_post_reachability");
        requireNoTerminalBypass(
                view, successPath, release,
                code + "_release_postdominance");
        requireNoTerminalBypass(
                view, release, record, code + "_record_postdominance");
        requireNoTerminalBypass(
                view, record, waitingWrite, code + "_waiting_postdominance");
        requireNoTerminalBypass(
                view, successStatus, successStatus + 3,
                code + "_success_status_join_postdominance");
        int paceStart = delay - 2;
        require(paceStart >= 0
                        && view.code.get(paceStart).instruction.getOpcode().name()
                                .equals("IGET_OBJECT")
                        && view.code.get(paceStart + 1).instruction.getOpcode().name()
                                .equals("IGET_OBJECT"),
                code + "_pacing_entry");
        requireNoTerminalBypass(
                view, paceStart, delay, code + "_pacing_delay_postdominance");
        requireNoTerminalBypass(
                view, delay, post, code + "_pacing_post_postdominance");
        verifyAutomaticReviewedTerminals(
                view, classes, waitingWrite, checkedPacing,
                pacingRefusalFinish, result,
                code + "_reviewed_terminals");
        verifySuccessInvocationClosure(
                view, classes, checkedPacing, true,
                code + "_unreviewed_invoke");
        result.automaticCompletionSaveCallCount = 1;
        result.automaticCompletionQuarantineBranchCount = 1;
        result.automaticOwnershipReleaseCallCount = 1;
        result.automaticSuccessRecordCallCount = 1;
        result.automaticWaitingClearWriteCount = 1;
        result.automaticPacedNextPostCount = 1;
        return post;
    }

    private static void verifyExactCatchallTry(
            MethodView view, int expectedStart, int expectedEnd,
            int expectedHandler, int handlerEnd, String code)
            throws ContractFailure {
        BaseTryBlock selected = null;
        for (Object tryObject : view.implementation.getTryBlocks()) {
            BaseTryBlock candidate = (BaseTryBlock) tryObject;
            int start = view.indexAt(
                    candidate.getStartCodeAddress(), code + "_start");
            int end = view.indexAt(
                    candidate.getStartCodeAddress()
                            + candidate.getCodeUnitCount(), code + "_end");
            if (start != expectedStart || end != expectedEnd) continue;
            require(selected == null, code + "_count");
            selected = candidate;
        }
        require(selected != null, code + "_extent");
        List<? extends ExceptionHandler> handlers =
                selected.getExceptionHandlers();
        require(handlers.size() == 1
                        && handlers.get(0).getExceptionType() == null
                        && view.indexAt(
                                handlers.get(0).getHandlerCodeAddress(),
                                code + "_handler_offset") == expectedHandler
                        && view.code.get(expectedHandler).instruction
                                .getOpcode().name().equals("MOVE_EXCEPTION"),
                code + "_handler");
        requireHandlerOnlyRange(
                view, expectedHandler, handlerEnd, code + "_handler");
        requireSoleExceptionalPredecessor(
                view, selected, expectedHandler, code);
    }

