    private static void verifyCompletionQuarantineCore(
            ClassDef schedulerClass, Map<String, ClassDef> classes,
            String code) throws ContractFailure {
        Method method = oneMethod(
                schedulerClass,
                contractSpec.quarantineCompletionReview.name,
                contractSpec.quarantineCompletionReview.descriptor,
                code + "_method_count");
        MethodView view = new MethodView(method);
        verifyNoUnreviewedImplicitThrow(
                view, code + "_unreviewed_implicit_throw");
        require(view.parameters.length == 3
                        && tryBlockCount(view) == 1
                        && view.code.size() == 13,
                code + "_shape");
        verifyAllowedResolvedInvocations(
                view, classes, Arrays.asList(
                        contractSpec.installLocalCompletionReview,
                        contractSpec.storeQuarantineCompletionReview,
                        contractSpec.hashSetConstructor,
                        contractSpec.hashSetAdd,
                        contractSpec.clearLocalCompletionReviewAfterRetry),
                code + "_unreviewed_invoke");
        verifyAllowedFieldReferences(
                view, Collections.emptySet(),
                code + "_unreviewed_field");

        require(invocationResolvesTo(
                        view.code.get(0).instruction, classes,
                        contractSpec.installLocalCompletionReview,
                        code + "_local_install"),
                code + "_local_install");
        int[] installRegisters = invocationRegisters(
                view.code.get(0).instruction);
        require(installRegisters.length == 2
                        && resolvesToRegister(
                                view, 0, installRegisters[0],
                                view.parameters[1])
                        && resolvesToRegister(
                                view, 0, installRegisters[1],
                                view.parameters[2]),
                code + "_local_install_arguments");
        require(view.code.get(1).instruction.getOpcode().name().equals("NOP")
                        && invocationResolvesTo(
                                view.code.get(2).instruction, classes,
                                contractSpec.storeQuarantineCompletionReview,
                                code + "_durable_store"),
                code + "_durable_store");
        int[] storeRegisters = invocationRegisters(
                view.code.get(2).instruction);
        require(storeRegisters.length == 3
                        && resolvesToRegister(
                                view, 2, storeRegisters[0],
                                view.parameters[0])
                        && resolvesToRegister(
                                view, 2, storeRegisters[1],
                                view.parameters[1])
                        && resolvesToRegister(
                                view, 2, storeRegisters[2],
                                view.parameters[2]),
                code + "_durable_store_arguments");
        int saved = moveResultScalarRegister(
                view, 2, code + "_durable_store_result");
        BaseTryBlock selected = (BaseTryBlock)
                view.implementation.getTryBlocks().iterator().next();
        require(view.indexAt(
                        selected.getStartCodeAddress(),
                        code + "_try_start") == 2
                        && view.indexAt(
                                selected.getStartCodeAddress()
                                        + selected.getCodeUnitCount(),
                                code + "_try_end") == 4,
                code + "_try_extent");
        List<? extends ExceptionHandler> handlers = selected.getExceptionHandlers();
        require(handlers.size() == 1
                        && handlers.get(0).getExceptionType() == null,
                code + "_handler_type");
        int handler = view.indexAt(
                handlers.get(0).getHandlerCodeAddress(),
                code + "_handler_offset");
        require(handler == 5
                        && view.code.get(4).instruction.getOpcode().name()
                                .startsWith("GOTO")
                        && offsetTarget(
                                view, 4,
                                view.code.get(4).instruction
                                        .getOpcode().name(),
                                code + "_normal_join") == 7
                        && view.code.get(5).instruction.getOpcode().name()
                                .equals("MOVE_EXCEPTION")
                        && isConstValue(
                                view.code.get(6).instruction, saved, 0),
                code + "_handler_shape");
        requireHandlerOnlyRange(view, 5, 6, code + "_handler");
        requireSoleExceptionalPredecessor(
                view, selected, 5, code + "_handler");
        require(branchTarget(
                        view, 7, "IF_EQZ", saved,
                        code + "_durable_result_branch")
                        == view.code.get(12).offset,
                code + "_durable_result_branch");
        Instruction allocation = view.code.get(8).instruction;
        int setRegister = ((OneRegisterInstruction) allocation).getRegisterA();
        require(isTypeInstruction(
                        allocation, "NEW_INSTANCE", setRegister,
                        "Ljava/util/HashSet;")
                        && referenceMatches(
                                view.code.get(9).instruction,
                                contractSpec.hashSetConstructor),
                code + "_retry_set_allocation");
        int[] constructorRegisters = invocationRegisters(
                view.code.get(9).instruction);
        int[] addRegisters = invocationRegisters(
                view.code.get(10).instruction);
        int[] clearRegisters = invocationRegisters(
                view.code.get(11).instruction);
        String setOrigin = originAt(view, 9, constructorRegisters[0]);
        require(constructorRegisters.length == 1
                        && addRegisters.length == 2
                        && clearRegisters.length == 2
                        && setOrigin.equals(originAt(
                                view, 10, addRegisters[0]))
                        && setOrigin.equals(originAt(
                                view, 11, clearRegisters[1]))
                        && resolvesToRegister(
                                view, 10, addRegisters[1],
                                view.parameters[2])
                        && resolvesToRegister(
                                view, 11, clearRegisters[0],
                                view.parameters[1]),
                code + "_retry_set_arguments");
        require(view.code.get(12).instruction.getOpcode().name()
                        .equals("RETURN")
                        && ((OneRegisterInstruction)
                                view.code.get(12).instruction).getRegisterA()
                                == saved,
                code + "_return_shape");
        requireNoTerminalBypass(
                view, 0, 2, code + "_install_store_postdominance");
        requireNoTerminalBypass(
                view, 8, 11, code + "_retry_clear_postdominance");
    }

